const SHOPIFY_ORDERS_REGISTRY = {};

// Configuración de conexión con Shopify Admin API y Google Sheets en Vivo
window.SHOPIFY_API_CONFIG = window.SHOPIFY_API_CONFIG || {
  shopDomain: 'detalgraf.myshopify.com',
  apiVersion: '2024-01',
  adminToken: '', // Token de acceso API Admin de Shopify (shpat_...)
  proxyUrl: 'https://script.google.com/macros/s/AKfycby3eA645Jyhg5zco6zpZUZmv4JNFiPS19Ahwg3k5EoocpQO6okiUNJz0m7tnka27LEC/exec',
  googleSheetUrl: 'https://script.google.com/macros/s/AKfycby3eA645Jyhg5zco6zpZUZmv4JNFiPS19Ahwg3k5EoocpQO6okiUNJz0m7tnka27LEC/exec'
};

let lastGoogleSheetSync = 0;

async function syncOrdersFromGoogleSheet(force = false) {
  const cfg = window.SHOPIFY_API_CONFIG;
  if (!cfg || !cfg.googleSheetUrl) return;
  const now = Date.now();
  if (!force && (now - lastGoogleSheetSync < 15000)) return;

  try {
    const res = await fetch(cfg.googleSheetUrl + '?t=' + now, {
      method: 'GET',
      redirect: 'follow'
    });
    if (res.ok) {
      const data = await res.json();
      if (data && Array.isArray(data.orders)) {
        lastGoogleSheetSync = now;
        data.orders.forEach(o => {
          if (!o || !o.orderNumber) return;
          const cleanNum = String(o.orderNumber).replace(/[^0-9]/g, '');
          const existing = SHOPIFY_ORDERS_REGISTRY['#' + cleanNum] || SHOPIFY_ORDERS_REGISTRY[cleanNum] || null;
          const stLower = String(o.statusTitle || '').toLowerCase();
          const stepNum = Number(o.step) || (stLower.includes('entregado') || stLower.includes('delivered') ? 3 : (stLower.includes('tránsito') || stLower.includes('transito') || stLower.includes('preparado') || stLower.includes('fulfilled') ? 2 : 1));
          const titleStr = stepNum === 3 ? 'Pedido entregado' : (stepNum === 2 ? 'Pedido en tránsito' : 'Pedido en preparación');
          const origDate = (existing && existing.dates && existing.dates[0]) ? existing.dates[0] : (o.fecha || (Array.isArray(o.dates) && o.dates[0]) || new Date().toISOString().slice(0, 10));
          const origDestino = (existing && existing.destino && !existing.destino.includes('Cobertura Nacional')) ? existing.destino : (o.destino || 'Bogotá, D.C.');
          const origGuia = (existing && existing.guia) ? existing.guia : (o.guia || ('DTL-2026-' + cleanNum));
          const formattedOrder = {
            orderNumber: cleanNum ? '#' + cleanNum : String(o.orderNumber),
            factura: (existing && existing.factura) || o.factura || ('Factura B2B #' + (cleanNum || o.orderNumber)),
            transportadora: (existing && existing.transportadora) || o.transportadora || 'Flota Propia Detalgraf',
            guia: origGuia,
            destino: origDestino,
            step: stepNum,
            statusTitle: titleStr,
            dates: [
              origDate,
              stepNum >= 2 ? 'Despachado' : 'Pendiente',
              stepNum === 3 ? 'Entregado' : 'Estimado 24-48h'
            ],
            history: [
              ...(stepNum === 3 ? [{ time: 'Completado', desc: 'Pedido entregado a satisfacción en ' + origDestino + '.' }] : []),
              ...(stepNum >= 2 ? [{ time: origDate, desc: 'Despachado con Flota Propia Detalgraf. Guía: ' + origGuia + '.' }] : []),
              { time: origDate, desc: 'Pedido #' + cleanNum + ' registrado y confirmado en Shopify.' }
            ]
          };

          SHOPIFY_ORDERS_REGISTRY[formattedOrder.orderNumber] = formattedOrder;
          SHOPIFY_ORDERS_REGISTRY[formattedOrder.orderNumber.toUpperCase()] = formattedOrder;
          if (cleanNum) {
            SHOPIFY_ORDERS_REGISTRY[cleanNum] = formattedOrder;
            SHOPIFY_ORDERS_REGISTRY['#' + cleanNum] = formattedOrder;
          }
          if (formattedOrder.guia) {
            SHOPIFY_ORDERS_REGISTRY[formattedOrder.guia] = formattedOrder;
            SHOPIFY_ORDERS_REGISTRY[formattedOrder.guia.toUpperCase()] = formattedOrder;
          }
        });
      }
    }
  } catch (err) {
    console.warn('Info: Sincronización Google Sheet:', err);
  }
}

setTimeout(() => { initOrdersRegistry(); syncOrdersFromGoogleSheet(true); }, 600);
setInterval(() => { syncOrdersFromGoogleSheet(true); }, 30 * 60 * 1000);

function formatShopifyApiOrder(so) {
  if (!so) return null;

  const orderNum = so.name || `#${so.order_number}`;
  const rawStatus = (so.fulfillment_status || '').toLowerCase();
  const deliveryStatus = (so.delivery_status || (so.fulfillments && so.fulfillments[0] && so.fulfillments[0].shipment_status) || '').toLowerCase();
  const tags = (Array.isArray(so.tags) ? so.tags.join(' ') : String(so.tags || '')).toLowerCase();
  const noteLower = String(so.note || '').toLowerCase();

  let orderStep = 1;
  let statusTitle = "Pedido en preparación";

  const fulfillments = Array.isArray(so.fulfillments) ? so.fulfillments : [];
  const hasDeliveredFulfillment = fulfillments.some(f => (f.shipment_status || '').toLowerCase() === 'delivered');
  const hasDeliveredTag = tags.includes('entregado') || tags.includes('delivered');
  const hasDeliveredNote = noteLower.includes('entregado');
  const isDelivered = deliveryStatus === 'delivered' || deliveryStatus === 'entregado' || hasDeliveredFulfillment || hasDeliveredTag || hasDeliveredNote;
  const isCancelled = !!so.cancelled_at;

  if (isCancelled) {
    orderStep = 1;
    statusTitle = `Pedido cancelado (${so.cancel_reason || 'Administración'})`;
  } else if (isDelivered) {
    // Si en Shopify está marcado como "Entregado"
    orderStep = 3;
    statusTitle = "Pedido entregado";
  } else if (rawStatus.includes('fulfilled') || rawStatus.includes('preparado') || rawStatus.includes('cumplido') || fulfillments.length > 0) {
    // REGLA OFICIAL: Solo cuando diga preparado en Shopify, en el tracking significa "Pedido en tránsito" (Paso 2)
    orderStep = 2;
    statusTitle = "Pedido en tránsito";
  } else {
    // "No preparado", "En preparación", "En espera"
    orderStep = 1;
    statusTitle = "Pedido en preparación";
  }

  let trackingCarrier = "Flota Propia Detalgraf";
  let trackingNumber = `DTL-2026-${so.order_number}`;
  if (Array.isArray(so.fulfillments) && so.fulfillments.length > 0) {
    const lastF = so.fulfillments[so.fulfillments.length - 1];
    if (lastF.tracking_company) trackingCarrier = lastF.tracking_company;
    if (lastF.tracking_number) trackingNumber = lastF.tracking_number;
  }

  let destCity = "Bogotá D.C.";
  if (so.shipping_address && so.shipping_address.city) {
    destCity = so.shipping_address.city;
    if (so.shipping_address.province) destCity += `, ${so.shipping_address.province}`;
  }

  const history = [];

  if (orderStep === 3) {
    history.push({
      time: "Completado",
      desc: `Pedido entregado a satisfacción en ${destCity}.`
    });
  }

  if (Array.isArray(so.fulfillments) && so.fulfillments.length > 0) {
    so.fulfillments.forEach(f => {
      history.push({
        time: f.created_at ? new Date(f.created_at).toLocaleDateString('es-CO', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : "Despacho",
        desc: `Despachado con ${f.tracking_company || trackingCarrier}. Guía: ${f.tracking_number || trackingNumber}.`
      });
    });
  } else if (orderStep >= 2) {
    history.push({
      time: "Despachado",
      desc: `En tránsito hacia ${destCity} vía ${trackingCarrier}. Guía: ${trackingNumber}.`
    });
  }

  if (so.note && typeof so.note === 'string' && so.note.trim()) {
    history.push({
      time: "Nota de Logística (Shopify Admin)",
      desc: so.note.trim()
    });
  }

  const totalFormat = typeof so.total_price !== 'undefined' ? `$${Math.round(parseFloat(so.total_price || 0)).toLocaleString('es-CO')} COP` : '';

  history.push({
    time: so.created_at ? new Date(so.created_at).toLocaleDateString('es-CO', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : "Registrado",
    desc: `Pedido ${orderNum} registrado y confirmado en plataforma Shopify.${totalFormat ? ' Total: ' + totalFormat + '.' : ''}`
  });

  return {
    orderNumber: orderNum,
    factura: `Factura Electrónica B2B #${so.order_number}`,
    transportadora: trackingCarrier,
    guia: trackingNumber,
    destino: destCity,
    step: orderStep,
    statusTitle: statusTitle,
    dates: [
      so.created_at ? new Date(so.created_at).toLocaleDateString('es-CO', { day: '2-digit', month: 'short' }) : "Registrado",
      orderStep >= 2 ? "Despachado" : "Pendiente despacho",
      orderStep === 3 ? "Entregado" : "Estimado 24-48h"
    ],
    history: history
  };
}

async function fetchLiveShopifyOrder(rawCode, digitsOnly) {
  const cfg = window.SHOPIFY_API_CONFIG;
  if (!cfg) return null;

  const targetName = digitsOnly || rawCode.replace('#', '');
  
  if (cfg.proxyUrl) {
    try {
      const url = `${cfg.proxyUrl}?order=${encodeURIComponent(targetName)}`;
      const res = await fetch(url);
      if (res.ok) {
        const data = await res.json();
        if (data && data.order) return formatShopifyApiOrder(data.order);
      }
    } catch(e) {
      console.warn('Error consultando Proxy de Tracking:', e);
    }
  }

  if (cfg.adminToken) {
    try {
      const endpoint = `https://${cfg.shopDomain}/admin/api/${cfg.apiVersion}/orders.json?name=${encodeURIComponent(targetName)}&status=any`;
      const res = await fetch(endpoint, {
        headers: {
          'X-Shopify-Access-Token': cfg.adminToken,
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      });
      if (res.ok) {
        const json = await res.json();
        if (json && Array.isArray(json.orders) && json.orders.length > 0) {
          return formatShopifyApiOrder(json.orders[0]);
        }
      }
    } catch(e) {
      console.warn('Error consultando Shopify Admin API:', e);
    }
  }

  return null;
}

