function initOrdersRegistry() {
  if (window.RAW_SHOPIFY_ORDERS && Array.isArray(window.RAW_SHOPIFY_ORDERS)) {
    window.RAW_SHOPIFY_ORDERS.forEach(o => {
      if (!o) return;
      if (o.orderNumber) {
        SHOPIFY_ORDERS_REGISTRY[o.orderNumber] = o;
        SHOPIFY_ORDERS_REGISTRY[o.orderNumber.toUpperCase()] = o;
        const cleanNum = o.orderNumber.replace(/[^0-9]/g, '');
        if (cleanNum) {
          SHOPIFY_ORDERS_REGISTRY[cleanNum] = o;
          SHOPIFY_ORDERS_REGISTRY['#' + cleanNum] = o;
        }
      }
      if (o.guia) {
        SHOPIFY_ORDERS_REGISTRY[o.guia] = o;
        SHOPIFY_ORDERS_REGISTRY[o.guia.toUpperCase()] = o;
      }
    });
  }

  for (const k in SHOPIFY_ORDERS_REGISTRY) {
    const o = SHOPIFY_ORDERS_REGISTRY[k];
    if (o.guia) {
      SHOPIFY_ORDERS_REGISTRY[o.guia.toUpperCase()] = o;
      SHOPIFY_ORDERS_REGISTRY[o.guia] = o;
    }
    if (o.orderNumber) {
      SHOPIFY_ORDERS_REGISTRY[o.orderNumber.toUpperCase()] = o;
      SHOPIFY_ORDERS_REGISTRY[o.orderNumber] = o;
      const numOnly = o.orderNumber.replace('#', '');
      SHOPIFY_ORDERS_REGISTRY[numOnly] = o;
    }
  }

  // Integrar órdenes en vivo del cliente desde Shopify Liquid (cuando inicia sesión)
  if (window.SHOPIFY_CUSTOMER && Array.isArray(window.SHOPIFY_CUSTOMER.orders)) {
    window.SHOPIFY_CUSTOMER.orders.forEach(so => {
      const guiaNumber = so.tracking_number || `DTL-2026-${so.order_number}`;
      const rawStatus = (so.raw_fulfillment_status || so.fulfillment_status || '').toLowerCase();
      const tags = (Array.isArray(so.tags) ? so.tags.join(' ') : String(so.tags || '')).toLowerCase();
      const noteLower = String(so.note || '').toLowerCase();
      
      const fulfillments = Array.isArray(so.fulfillments) ? so.fulfillments : [];
      const hasDeliveredFulfillment = fulfillments.some(f => (f.shipment_status || '').toLowerCase() === 'delivered');
      const hasDeliveredTag = tags.includes('entregado') || tags.includes('delivered');
      const hasDeliveredNote = noteLower.includes('entregado');
      let daysOld = 999;
      if (so.created_at) {
        const cDate = new Date(so.created_at);
        daysOld = (Date.now() - cDate.getTime()) / (1000 * 60 * 60 * 24);
      }

      let orderStep = 1;
      let statusTitle = "Pedido en preparación";

      if (so.cancelled) {
        orderStep = 1;
        statusTitle = `Pedido cancelado (${so.cancel_reason || 'Administración'})`;
      } else if (hasDeliveredFulfillment || hasDeliveredTag || hasDeliveredNote) {
        orderStep = 3;
        statusTitle = "Pedido entregado";
      } else if (rawStatus.includes('fulfilled') || rawStatus.includes('preparado') || rawStatus.includes('cumplido') || rawStatus.includes('partial') || rawStatus.includes('transit') || rawStatus.includes('ruta') || fulfillments.length > 0 || (so.tracking_url && so.tracking_url.length > 5)) {
        orderStep = 2;
        statusTitle = "Pedido en tránsito";
      } else if (tags.includes('transito') || tags.includes('en ruta') || tags.includes('despach') || noteLower.includes('despach')) {
        orderStep = 2;
        statusTitle = "Pedido en tránsito";
      } else {
        orderStep = 1;
        statusTitle = "Pedido en preparación";
      }

      // Extraer notas del administrador / jefe puestas en Shopify Admin
      const adminNotes = [];
      if (so.note && typeof so.note === 'string' && so.note.trim().length > 0) {
        const lines = so.note.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
        lines.forEach(l => {
          adminNotes.push(l);
        });
      }

      // Construir historial cronológico (el más reciente primero para el timeline del tracking)
      const dynamicHistory = [];

      // A. Si fue cancelado en administración
      if (so.cancelled) {
        dynamicHistory.push({
          time: "Cancelado",
          desc: `Cancelación registrada en Shopify Admin. Motivo: ${so.cancel_reason || 'Solicitud administrativa'}.`
        });
      }

      // B. Si está entregado / cumplido
      if (orderStep === 3) {
        dynamicHistory.push({
          time: (so.fulfillments && so.fulfillments[0] && so.fulfillments[0].updated_at) ? so.fulfillments[0].updated_at : "Completado",
          desc: `Entrega completada exitosamente a satisfacción en ${so.shipping_city || 'dirección registrada'}.`
        });
      }

      // C. Notas y comentarios directos puestos por el jefe en Shopify Admin -> Pedidos
      adminNotes.forEach(noteText => {
        dynamicHistory.push({
          time: "Nota de Logística (Shopify Admin)",
          desc: noteText
        });
      });

      // D. Fulfillments / Guías creadas por el jefe en Shopify
      if (Array.isArray(so.fulfillments) && so.fulfillments.length > 0) {
        so.fulfillments.forEach(f => {
          const comp = f.tracking_company || so.tracking_company || "Transportadora";
          const num = f.tracking_number || so.tracking_number;
          const statusText = f.status === 'success' ? 'Entregado a transportadora' : 'En proceso de despacho logístico';
          dynamicHistory.push({
            time: f.created_at || "Despacho",
            desc: `${statusText} (${comp}). Guía: ${num || 'Generada'}.`
          });
        });
      } else if (orderStep >= 2) {
        dynamicHistory.push({
          time: "Despachado",
          desc: `Despachado vía ${so.tracking_company || 'Flota Propia Detalgraf'}. Guía de entrega: ${guiaNumber}.`
        });
      }

      // E. Alistamiento en bodega
      dynamicHistory.push({
        time: "Bodega Detalgraf",
        desc: "Alistamiento técnico y empaque de suministros verificado en bodega central."
      });

      // F. Registro original del pedido
      dynamicHistory.push({
        time: so.created_at || "Registrado",
        desc: `Pedido ${so.name || '#' + so.order_number} recibido en plataforma Shopify. Total: $${so.total_price}.`
      });

      const rec = {
        orderNumber: so.name || `#${so.order_number}`,
        factura: `Factura Electrónica DIAN #${so.order_number}`,
        transportadora: so.tracking_company || "Flota Propia Detalgraf",
        guia: guiaNumber,
        destino: so.shipping_city ? `Ciudad de Entrega: ${so.shipping_city}` : "Destino Registrado en Pedido",
        step: orderStep,
        statusTitle: statusTitle,
        orderStatusUrl: so.order_status_url || "",
        dates: [
          so.created_at || "Registrado",
          orderStep >= 2 ? "Despachado" : "Pendiente despacho",
          orderStep === 3 ? "Entregado con éxito" : "Estimado 24-48h"
        ],
        history: dynamicHistory
      };
      SHOPIFY_ORDERS_REGISTRY[String(so.order_number)] = rec;
      SHOPIFY_ORDERS_REGISTRY[`#${so.order_number}`] = rec;
      SHOPIFY_ORDERS_REGISTRY[guiaNumber.toUpperCase()] = rec;
      if (so.name) SHOPIFY_ORDERS_REGISTRY[so.name.toUpperCase()] = rec;
    });
  }

  // Integrar último pedido guardado en la sesión local (si no existe en Shopify)
  try {
    const savedOrderStr = localStorage.getItem('nqc_last_order');
    if (savedOrderStr) {
      const savedObj = JSON.parse(savedOrderStr);
      if (savedObj && savedObj.orderNumber) {
        const cleanNum = savedObj.orderNumber.replace('#', '');
        if (!SHOPIFY_ORDERS_REGISTRY[cleanNum]) {
          SHOPIFY_ORDERS_REGISTRY[cleanNum] = savedObj;
          SHOPIFY_ORDERS_REGISTRY['#' + cleanNum] = savedObj;
          if (savedObj.guia) SHOPIFY_ORDERS_REGISTRY[savedObj.guia.toUpperCase()] = savedObj;
        }
      }
    }
  } catch(e) {}
}

function renderTrackingOrder(order) {
  currentTrackOrder = order;

  const stText = document.getElementById('nqcStatusText');
  const stBadge = document.getElementById('nqcStatusBadge');
  const dispFactura = document.getElementById('nqcFacturaText');
  const dispTrans = document.getElementById('nqcTransportadoraText');
  const dispGuia = document.getElementById('nqcGuiaText');
  const dispDestino = document.getElementById('nqcDestinoText');

  // Escala oficial de 3 estados de la barra (En Preparación, En Tránsito, Entregado)
  let step3 = 1;
  const rawTitle = (order.statusTitle || '').toLowerCase();
  if (rawTitle.includes('entregad') || (!rawTitle.includes('tránsito') && !rawTitle.includes('transito') && !rawTitle.includes('despach') && (order.step === 3 || order.step === 4))) {
    step3 = 3;
  } else if (order.step === 2 || rawTitle.includes('tránsito') || rawTitle.includes('transito') || rawTitle.includes('despach') || rawTitle.includes('ruta')) {
    step3 = 2;
  } else {
    step3 = 1;
  }

  const title = order.statusTitle || (step3 === 3 ? 'Pedido entregado' : step3 === 2 ? 'Pedido en tránsito' : 'Pedido en preparación');
  if (stText) stText.textContent = title;

  if (stBadge) {
    stBadge.className = 'nqc-status-badge ' + (
      step3 === 3 ? 'nqc-badge-delivered' :
      step3 === 2 ? 'nqc-badge-transit' : 'nqc-badge-prep'
    );
  }

  if (dispFactura) dispFactura.textContent = order.factura || 'Factura B2B';
  if (dispTrans) dispTrans.textContent = 'Transportadora: ' + (order.transportadora || 'Envía / Flota Detalgraf');
  if (dispGuia) dispGuia.textContent = order.guia || order.orderNumber;
  if (dispDestino) dispDestino.textContent = order.destino || 'Bogotá D.C.';

  for (let i = 1; i <= 3; i++) {
    const stepEl = document.getElementById(`nqcStep${i}`);
    const lineEl = document.getElementById(`nqcLine${i}`);
    const circEl = document.getElementById(`nqcStepCirc${i}`);
    const dateEl = document.getElementById(`nqcStep${i}Date`);

    if (stepEl) {
      stepEl.classList.remove('completed', 'active');
      if (i < step3 || (i === 3 && step3 === 3)) {
        stepEl.classList.add('completed');
      } else if (i === step3) {
        stepEl.classList.add('active');
      }
    }

    if (lineEl) {
      lineEl.classList.remove('nqc-line-completed', 'active');
      if (i < step3) {
        lineEl.classList.add('nqc-line-completed', 'active');
      }
    }

    if (circEl) {
      if (i < step3 || (i === 3 && step3 === 3)) {
        circEl.innerHTML = '✓';
      } else if (i === step3) {
        circEl.innerHTML = '<div class="nqc-inner-active-dot"></div>';
      } else {
        circEl.innerHTML = '';
      }
    }

    if (dateEl && order.dates) {
      if (order.dates.length === 3) {
        dateEl.textContent = order.dates[i - 1] || '--';
      } else if (order.dates.length >= 4) {
        // Omitir Confirmado y usar los 3 últimos estados solicitados por el jefe
        dateEl.textContent = order.dates[i] || '--';
      } else {
        dateEl.textContent = order.dates[i - 1] || '--';
      }
    }
  }

  const historyList = document.getElementById('nqcHistoryList');
  if (historyList) {
    historyList.innerHTML = '';
    (order.history || []).forEach((item, idx) => {
      const li = document.createElement('li');
      li.className = 'nqc-history-item' + (idx === 0 ? ' active' : '');
      const isBossNote = (item.time || '').includes('Shopify');
      const dotColor = idx === 0 ? '#0284c7' : (isBossNote ? '#059669' : '#94a3b8');
      const timeHtml = isBossNote
        ? `<span style="display:inline-flex; align-items:center; gap:4px; font-weight:800; color:#065f46; background:#d1fae5; padding:2px 8px; border-radius:4px; font-size:11px;">💬 ${item.time}</span>`
        : `<span style="font-weight:700; color:#1e293b; margin-right:8px; white-space:nowrap;">${item.time}</span>`;

      li.innerHTML = `
        <span style="display:inline-block; width:10px; height:10px; border-radius:50%; background:${dotColor}; margin-right:12px; flex-shrink:0;"></span>
        ${timeHtml}
        <span style="color:#94a3b8; margin-right:8px; margin-left:4px;">—</span>
        <span style="color:${isBossNote ? '#0f172a; font-weight:600' : '#475569'};">${item.desc}</span>
      `;
      historyList.appendChild(li);
    });
  }


}

async function doTrackingLookup() {
  initOrdersRegistry();
  await syncOrdersFromGoogleSheet(false);
  const input = document.getElementById('nqcTrackingInput') || document.getElementById('trackingInput');
  const rawCode = (input ? input.value : '').trim();

  if (!rawCode) {
    if (typeof showToastNotification === 'function') {
      showToastNotification(0, 'Por favor ingresa un número de pedido (Ej: #2690)', 0, true);
    } else {
      alert('Por favor ingresa un número de pedido o guía (Ej: #2690)');
    }
    return;
  }

  const codeUpper = rawCode.toUpperCase();
  const digitsOnly = rawCode.replace(/[^0-9]/g, '');

  let found = null;

  function findInRegistry() {
    if (SHOPIFY_ORDERS_REGISTRY[codeUpper]) {
      return SHOPIFY_ORDERS_REGISTRY[codeUpper];
    }
    if (rawCode.startsWith('#') && SHOPIFY_ORDERS_REGISTRY[codeUpper.replace('#', '')]) {
      return SHOPIFY_ORDERS_REGISTRY[codeUpper.replace('#', '')];
    }
    if (digitsOnly && SHOPIFY_ORDERS_REGISTRY[digitsOnly]) {
      return SHOPIFY_ORDERS_REGISTRY[digitsOnly];
    }
    if (digitsOnly && SHOPIFY_ORDERS_REGISTRY['#' + digitsOnly]) {
      return SHOPIFY_ORDERS_REGISTRY['#' + digitsOnly];
    }
    // Coincidencia exacta por número de guía
    for (const k in SHOPIFY_ORDERS_REGISTRY) {
      const reg = SHOPIFY_ORDERS_REGISTRY[k];
      if (reg && reg.guia && reg.guia.toUpperCase() === codeUpper) {
        return reg;
      }
    }
    return null;
  }

  // 1. Coincidencia exacta en base de datos o registro de órdenes
  found = findInRegistry();

  // 2. Si no se encontró en memoria, forzar actualización inmediata desde Google Sheets por si acaba de crearse el pedido
  if (!found) {
    await syncOrdersFromGoogleSheet(true);
    found = findInRegistry();
  }

  // 3. CONSULTA EN VIVO A SHOPIFY ADMIN API (SI HAY TOKEN / PROXY CONFIGURADO)
  if (!found && (window.SHOPIFY_API_CONFIG && (window.SHOPIFY_API_CONFIG.adminToken || window.SHOPIFY_API_CONFIG.proxyUrl))) {
    const btnTrack = document.getElementById('nqcBtnTrack');
    const oldBtnText = btnTrack ? btnTrack.textContent : '';
    if (btnTrack) {
      btnTrack.disabled = true;
      btnTrack.textContent = 'Consultando...';
    }
    try {
      found = await fetchLiveShopifyOrder(rawCode, digitsOnly);
      if (found) {
        SHOPIFY_ORDERS_REGISTRY[codeUpper] = found;
        if (digitsOnly) SHOPIFY_ORDERS_REGISTRY[digitsOnly] = found;
      }
    } catch(err) {
      console.warn('Error en fetchLiveShopifyOrder:', err);
    } finally {
      if (btnTrack) {
        btnTrack.disabled = false;
        btnTrack.textContent = oldBtnText || 'Rastrear Envío';
      }
    }
  }

  const resultCard = document.getElementById('nqcTrackingResult');
  const errorCard = document.getElementById('trackingLookupError');
  const errorMsg = document.getElementById('trackingLookupErrorMsg');
  const btnErrorEmail = document.getElementById('btnErrorEmail');

  if (found) {
    if (errorCard) errorCard.style.display = 'none';
    renderTrackingOrder(found);
    if (resultCard) {
      resultCard.style.display = 'block';
      resultCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  } else {
    if (resultCard) resultCard.style.display = 'none';
    if (errorCard) {
      errorCard.style.display = 'block';
      if (errorMsg) {
        errorMsg.innerHTML = `El código <strong>${rawCode}</strong> no corresponde a un número de orden o guía válido. Por favor verifique el número en su confirmación de compra (Ej: <strong>#2690</strong>) o comuníquese con nosotros a <strong>info@detalgraf.com</strong>.`;
      }
      if (btnErrorEmail) {
        btnErrorEmail.href = `mailto:info@detalgraf.com?subject=` + encodeURIComponent(`Consulta Despacho Pedido ${rawCode}`) + `&body=` + encodeURIComponent(`Hola equipo Detalgraf,\n\nSolicito información del estado de entrega del pedido número ${rawCode}.\n\nMuchas gracias.`);
      }
      errorCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }
}

function clearTrackingSearch() {
  const input = document.getElementById('nqcTrackingInput') || document.getElementById('trackingInput');
  if (input) {
    input.value = '';
    input.focus();
  }
  const resultCard = document.getElementById('nqcTrackingResult');
  const errorCard = document.getElementById('trackingLookupError');
  if (resultCard) resultCard.style.display = 'none';
  if (errorCard) errorCard.style.display = 'none';
}

function setAndTrackGuia(guia) {
  const input = document.getElementById('nqcTrackingInput') || document.getElementById('trackingInput');
  if (input) input.value = guia;
  doTrackingLookup();
}

