function initTrackingSessionUI() {
  try {
    const urlParams = new URLSearchParams(window.location.search);
    const trackingQuery = urlParams.get('tracking') || urlParams.get('guia') || urlParams.get('order') || urlParams.get('q');
    const updateStep = urlParams.get('step') || urlParams.get('estado');
    const updateNote = urlParams.get('nota') || urlParams.get('novedad');

    if (trackingQuery) {
      if (updateStep) {
        initOrdersRegistry();
        const clean = trackingQuery.replace('#', '').trim();
        const num = parseInt(clean.replace(/[^0-9]/g, ''), 10) || 2692;
        let ord = SHOPIFY_ORDERS_REGISTRY[clean] || SHOPIFY_ORDERS_REGISTRY['#' + clean];
        const stepNum = parseInt(updateStep, 10) || 2;
        const titleText = stepNum === 3 ? "Pedido entregado" : stepNum === 2 ? "Pedido en tránsito" : "Pedido en preparación";
        if (!ord) {
          ord = {
            orderNumber: `#${num}`,
            factura: `Factura B2B #FE-${8940 + (num > 2690 ? num - 2690 : num)}`,
            transportadora: "Flota Propia Detalgraf",
            guia: `DTL-2026-${num}`,
            destino: "Bogotá D.C.",
            step: stepNum,
            statusTitle: titleText,
            dates: ["Hoy", "Hoy", "Hoy"],
            history: [{ time: "Hoy", desc: updateNote || "Estado actualizado vía enlace logístico", active: true }]
          };
        } else {
          ord.step = stepNum;
          ord.statusTitle = titleText;
          if (updateNote) {
            if (!Array.isArray(ord.history)) ord.history = [];
            ord.history.unshift({ time: "Hoy", desc: updateNote, active: true });
          }
        }
      }
      setAndTrackGuia(trackingQuery);
      return;
    }
    const lastOrderStr = localStorage.getItem('nqc_last_order');
    if (lastOrderStr && (window.location.hash === '#tracking' || window.location.hash === '#track')) {
      try {
        const lastOrder = JSON.parse(lastOrderStr);
        if (lastOrder && lastOrder.guia) {
          const input = document.getElementById('nqcTrackingInput') || document.getElementById('trackingInput');
          if (input && !input.value) {
            input.value = lastOrder.guia;
          }
        }
      } catch(e) {}
    }
  } catch(e) {
    console.warn('initTrackingSessionUI non-fatal:', e);
  }
}
window.initTrackingSessionUI = initTrackingSessionUI;

// ========================================================================
// INTERCEPTOR DE NAVEGACIÓN (LOGO, MENÚ TIENDA Y CATEGORÍAS)
// Evita recargar 'detalshop.com' y mantiene la experiencia en preview/SPA
// ========================================================================
function initNavigationLinkInterceptors() {
  document.addEventListener('click', function(e) {
    // 0. Toggle de submenús en el Drawer móvil (Botón + o enlace)
    const toggleBtn = e.target.closest('.mobile-nav__toggle-btn, .mobile-nav__toggle');
    if (toggleBtn) {
      e.preventDefault();
      const parentItem = toggleBtn.closest('.mobile-nav__item') || toggleBtn.closest('.mobile-nav__has-sublist');
      const sublist = parentItem ? parentItem.querySelector('.mobile-nav__sublist') : null;
      if (sublist) {
        const isShown = sublist.style.display === 'block';
        sublist.style.display = isShown ? 'none' : 'block';
        toggleBtn.setAttribute('aria-expanded', isShown ? 'false' : 'true');
        toggleBtn.classList.toggle('active', !isShown);
        if (parentItem) parentItem.classList.toggle('mobile-nav--expanded', !isShown);
      }
      return;
    }

    // 0. Clic en el Carrito del Header o cualquier botón de carrito
    const cartTrigger = e.target.closest('.cart-link, .site-nav__cart-count, #headerCartCount, [data-cart-link], a[href="/cart"], a[href*="/cart"]');
    if (cartTrigger) {
      e.preventDefault();
      e.stopPropagation();
      closeNavDrawer();
      openCartDrawer();
      return;
    }

    // 1. Clic en el Logo de la tienda
    const logoLink = e.target.closest('.site-header__logo-link, .site-header__logo a, .default-logo, [itemprop="logo"]');
    if (logoLink) {
      const onIndex = document.getElementById('mainWebsite') !== null;
      if (onIndex) {
        e.preventDefault();
        closeNavDrawer();
        switchView('home');
        window.scrollTo({ top: 0, behavior: 'smooth' });
        return;
      }
    }

    // 2. Clic en enlace de navegación
    const navLink = e.target.closest('.site-nav__link, .dropdown-link, .mobile-nav__link, a');
    if (!navLink) return;

    const href = navLink.getAttribute('href') || '';
    const text = (navLink.textContent || '').trim().toLowerCase();

    // Rastrear Pedido / Envíos
    if (text.includes('rastrear') || href.includes('#tracking') || href.includes('tracking') || href.includes('order-tracking')) {
      e.preventDefault();
      closeNavDrawer();
      if (typeof switchView === 'function') {
        switchView('track');
      }
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }

    // Quiénes Somos
    if (text.includes('quiénes') || text.includes('quienes') || href.includes('#quienes-somos') || href.includes('quienes-somos')) {
      e.preventDefault();
      closeNavDrawer();
      if (typeof openQuienesSomosModal === 'function') {
        openQuienesSomosModal();
      }
      return;
    }

    // Búsqueda en Drawer
    if (text.includes('búsqueda') || text.includes('busqueda') || href === '/search') {
      e.preventDefault();
      closeNavDrawer();
      const sInput = document.getElementById('nqcSearchInput') || document.querySelector('input[type="search"]');
      if (sInput) {
        sInput.focus();
        sInput.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
      return;
    }

    // Contáctenos en Drawer
    if (text.includes('contáctenos') || text.includes('contactenos') || href.includes('/pages/contact')) {
      e.preventDefault();
      closeNavDrawer();
      const footer = document.querySelector('footer, .site-footer');
      if (footer) footer.scrollIntoView({ behavior: 'smooth' });
      return;
    }

    if (text === 'inicio' || href === '/' || href.endsWith('.com/') || href.endsWith('.com')) {
      const onIndex = document.getElementById('mainWebsite') !== null;
      if (onIndex) {
        e.preventDefault();
        closeNavDrawer();
        switchView('home');
        window.scrollTo({ top: 0, behavior: 'smooth' });
        return;
      }
    }

    // 3. Clic en "Tienda" principal
    if (text === 'tienda' || text.startsWith('tienda')) {
      // Si está en el drawer y tiene toggle, permitimos alternar el submenú
      if (navLink.classList.contains('mobile-nav__toggle-link') || navLink.closest('.mobile-nav__has-sublist')) {
        const parentItem = navLink.closest('.mobile-nav__item') || navLink.closest('.mobile-nav__has-sublist');
        const sublist = parentItem ? parentItem.querySelector('.mobile-nav__sublist') : null;
        if (sublist) {
          e.preventDefault();
          const isShown = sublist.style.display === 'block';
          sublist.style.display = isShown ? 'none' : 'block';
          if (parentItem) parentItem.classList.toggle('mobile-nav--expanded', !isShown);
          return;
        }
      }
      const onIndex = document.getElementById('mainWebsite') !== null;
      if (onIndex) {
        if (!navLink.classList.contains('dropdown-link')) {
          e.preventDefault();
          closeNavDrawer();
          switchView('home');
          scrollToCatalog();
          return;
        }
      }
    }

    // 4. Clic en items de categoría dentro del menú "Tienda"
    if (navLink.classList.contains('dropdown-link') || href.includes('/collections/') || navLink.closest('.mobile-nav__sublist')) {
      let catToFilter = null;
      if (text.includes('bioseguridad') || href.includes('bioseguridad')) catToFilter = 'Bioseguridad';
      else if (text.includes('aseo') || href.includes('aseo')) catToFilter = 'Aseo';
      else if (text.includes('cafeter') || href.includes('cafeteria')) catToFilter = 'Cafeteria';
      else if (text.includes('seguridad') || href.includes('seguridad')) catToFilter = 'Seguridad';
      else if (text.includes('papeler') || href.includes('papeleria')) catToFilter = 'Papeleria';

      if (catToFilter) {
        const onIndex = document.getElementById('mainWebsite') !== null;
        if (onIndex) {
          e.preventDefault();
          closeNavDrawer();
          switchView('home');
          filterHomeCatalog(catToFilter);
          scrollToCatalog();
          return;
        }
      }
    }
  });
}

function openQuienesSomosModal() {
      const modal = document.getElementById('quienesSomosModal');
      if (modal) {
        modal.style.setProperty('display', 'flex', 'important');
        modal.classList.add('active');
      }
    }
    window.openQuienesSomosModal = openQuienesSomosModal;

    function closeQuienesSomosModal(e) {
      if (!e || e.target === document.getElementById('quienesSomosModal') || (e.target.closest && e.target.closest('.btn-close-quienes')) || (e.target.tagName === 'BUTTON' && e.target.textContent.includes('Entendido'))) {
        const modal = document.getElementById('quienesSomosModal');
        if (modal) {
          modal.style.setProperty('display', 'none', 'important');
          modal.classList.remove('active');
        }
      }
    }
    window.closeQuienesSomosModal = closeQuienesSomosModal;

    window.openCartDrawer = openCartDrawer;
    window.closeCartDrawer = closeCartDrawer;
    window.addToCart = addToCart;
    window.removeFromCart = removeFromCart;
    window.removeCartItem = removeFromCart;
    window.updateCartItemQty = updateCartItemQty;
    window.changeCardQty = changeCardQty;
    window.handleCardQtyDirectChange = handleCardQtyDirectChange;
    window.addCardQtyToCart = addCardQtyToCart;
    window.setAndAddQty = setAndAddQty;
    window.setCartZone = setCartZone;
    window.proceedCheckoutFigma = proceedCheckoutFigma;
    window.handleDrawerCartSubmit = handleDrawerCartSubmit;
    window.switchView = switchView;
    window.filterHomeCatalog = filterHomeCatalog;
    window.handleCatalogSearch = handleCatalogSearch;
    window.clearCatalogSearch = clearCatalogSearch;
    window.doTrackingLookup = doTrackingLookup;
    window.trackOrderDirect = doTrackingLookup;
    window.clearTrackingSearch = clearTrackingSearch;
    window.trackOrderDirect = doTrackingLookup;
    window.clearTrackingSearch = clearTrackingSearch;
    window.setAndTrackGuia = setAndTrackGuia;
    window.openPdpWithProduct = openPdpWithProduct;
    window.openPdfModal = openPdfModal;
    window.closePdfModal = closePdfModal;
    window.downloadOrPrintPdf = downloadOrPrintPdf;
        function openIconModal() {
      const modal = document.getElementById('iconModalOverlay');
      if (modal) modal.classList.add('active');
    }
    function closeIconModal(e) {
      if (!e || e.target === document.getElementById('iconModalOverlay') || (e.target && e.target.tagName === 'BUTTON')) {
        const modal = document.getElementById('iconModalOverlay');
        if (modal) modal.classList.remove('active');
      }
    }

    window.openIconModal = openIconModal;
    window.closeIconModal = closeIconModal;
    window.generateCartQuotePDF = generateCartQuotePDF;

    // VINCULACIÓN GLOBAL DE TODOS LOS BOTONES DE CARRITO DE LA TIENDA
    document.addEventListener('click', function(e) {
      if (e.target.closest('#nqcDrawerCartForm a, .drawer-footer a[href*="/cart"]')) return;
      const cartTrigger = e.target.closest('.cart-link, .js-drawer-open-button-right, .btn-sticky-open-cart, .btn-toast-view, a[href="/cart"], .header-icon-action[title="Carrito"]');
      if (cartTrigger) {
        e.preventDefault();
        openCartDrawer();
      }
    });

    // ENRUTAMIENTO POR HASH (#tracking, #track, #home)
    function handleHashNavigation() {
      const hash = (window.location.hash || '').toLowerCase();
      const path = (window.location.pathname || '').toLowerCase();
      if (hash.includes('track') || path.includes('track') || path.includes('rastreo')) {
        if (typeof switchView === 'function') switchView('track');
      } else if (hash.includes('pdp')) {
        if (typeof switchView === 'function') switchView('pdp');
      } else if (hash.includes('home') || hash.includes('inicio') || hash.includes('catalogo')) {
        if (typeof switchView === 'function') switchView('home');
      }
    }
    window.addEventListener('hashchange', handleHashNavigation);
    window.addEventListener('load', handleHashNavigation);

    window.loadMoreProducts = loadMoreProducts;

    // VINCULACIÓN DE LA BARRA DE MENÚ Y ENLACES GLOBALES CON LA NUEVA INTERFAZ REACTIVA
    document.addEventListener('click', function(e) {
      const link = e.target.closest('a');
      if (!link) return;

      const href = (link.getAttribute('href') || '').toLowerCase().trim();
      const text = (link.textContent || '').toLowerCase().trim();

      // Cerrar menú móvil si está abierto al interactuar
      function maybeCloseMobileNav() {
        if (window.timber && window.timber.LeftDrawer && typeof window.timber.LeftDrawer.close === 'function') {
          window.timber.LeftDrawer.close();
        }
        const navDrawer = document.getElementById('NavDrawer');
        if (navDrawer && navDrawer.classList.contains('is-open')) {
          const closeBtn = navDrawer.querySelector('.drawer__close-button');
          if (closeBtn) closeBtn.click();
        }
      }

      // 1. Quiénes Somos (Modal)
      if (text.includes('quiénes somos') || text.includes('quienes somos') || href.includes('quienes-somos')) {
        e.preventDefault();
        maybeCloseMobileNav();
        openQuienesSomosModal();
        return;
      }

      // 2. Rastrear Pedido / Tracking
      if (text.includes('tracking') || text.includes('rastrear') || text.includes('rastreo') || text.includes('seguimiento') || href.includes('tracking') || href.includes('#track')) {
        e.preventDefault();
        maybeCloseMobileNav();
        switchView('track');
        return;
      }

      // 3. Inicio / Home
      if (href === '/' || href === '#home' || href === '#inicio' || text === 'inicio' || text === 'home') {
        if (document.getElementById('viewHome')) {
          e.preventDefault();
          maybeCloseMobileNav();
          switchView('home');
          window.scrollTo({ top: 0, behavior: 'smooth' });
          return;
        }
      }

      // 4. Categorías / Líneas de productos vinculadas con el catálogo interactivo
      if (document.getElementById('catalogSection')) {
        if (text.includes('aseo') || href.includes('/aseo') || href.includes('linea-aseo')) {
          e.preventDefault();
          maybeCloseMobileNav();
          switchView('home');
          filterHomeCatalog('Aseo');
          scrollToCatalog();
          return;
        }
        if (text.includes('seguridad') || text.includes('bioseguridad') || href.includes('/seguridad') || href.includes('/bioseguridad')) {
          e.preventDefault();
          maybeCloseMobileNav();
          switchView('home');
          filterHomeCatalog('Seguridad');
          scrollToCatalog();
          return;
        }
        if (text.includes('cafetería') || text.includes('cafeteria') || href.includes('/cafeteria')) {
          e.preventDefault();
          maybeCloseMobileNav();
          switchView('home');
          filterHomeCatalog('Cafeteria');
          scrollToCatalog();
          return;
        }
        if (text.includes('papelería') || text.includes('papeleria') || href.includes('/papeleria')) {
          e.preventDefault();
          maybeCloseMobileNav();
          switchView('home');
          filterHomeCatalog('Papeleria');
          scrollToCatalog();
          return;
        }
        if (text.includes('químicos') || text.includes('quimicos') || href.includes('/quimicos')) {
          e.preventDefault();
          maybeCloseMobileNav();
          switchView('home');
          filterHomeCatalog('Quimicos');
          scrollToCatalog();
          return;
        }
        if (text.includes('catálogo') || text.includes('catalogo') || text.includes('todas las líneas') || text.includes('productos') || href.includes('/collections/all')) {
          e.preventDefault();
          maybeCloseMobileNav();
          switchView('home');
          filterHomeCatalog('Todos');
          scrollToCatalog();
          return;
        }
      }
    });

    // SOPORTE DEL BOTÓN DE RETORNO NATIVO DEL NAVEGADOR (POPSTATE)
    window.addEventListener('popstate', function(e) {
      if (e.state && e.state.view === 'pdp' && e.state.productId) {
        populatePdpData(e.state.productId);
        document.querySelectorAll('.page-view-block').forEach(el => el.classList.remove('active'));
        var vp = document.getElementById('viewPdp'); if (vp) vp.classList.add('active');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else if (e.state && (e.state.view === 'track' || e.state.view === 'tracking')) {
        document.querySelectorAll('.page-view-block').forEach(el => el.classList.remove('active'));
        var vt = document.getElementById('viewTrack'); if (vt) vt.classList.add('active');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
        document.querySelectorAll('.page-view-block').forEach(el => el.classList.remove('active'));
        var vh = document.getElementById('viewHome'); if (vh) vh.classList.add('active');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    });

    // INICIALIZAR CATÁLOGO Y PROCESAR PARÁMETROS URL CUANDO EL DOM ESTÉ LISTO
    document.addEventListener('DOMContentLoaded', function() {
      if (typeof renderCatalog === 'function') {
        renderCatalog(true);
      }
      if (typeof updateCartUI === 'function') {
        updateCartUI();
      }
      if (typeof syncShopifyServerCart === 'function') {
        syncShopifyServerCart();
      }
      if (typeof populatePdpData === 'function' && typeof PRODUCTS_DATA !== 'undefined' && PRODUCTS_DATA.length > 0) {
        populatePdpData(PRODUCTS_DATA[0].id);
      }

      // Parámetros de URL para navegación integrada
      try {
        const urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get('openCart') === '1' || window.location.hash === '#cart') {
          setTimeout(openCartDrawer, 350);
        }
        const pdpParam = urlParams.get('pdp') || urlParams.get('product');
        if (pdpParam) {
          setTimeout(function() {
            openPdpWithProduct(pdpParam);
          }, 300);
        }
        const colParam = urlParams.get('collection');
        if (colParam && typeof filterHomeCatalog === 'function') {
          setTimeout(function() {
            filterHomeCatalog(colParam);
            scrollToCatalog();
          }, 300);
        }
      } catch(e) {}
    });
